powerpagecomponent.content:
{
  "source": " {% comment %}
sections--acceptance-sponsorship

Supports:
- Donation acceptance contact capture
- Individual and organisation donations
- Accessible client-side validation
- Offering Acceptance PATCH update
- Redirect back through the Offering Acceptance router

Temporary:
- Styles remain embedded for testing.
- Reusable class names are ready for later extraction into:
  - css--theme-client
  - css--site
{% endcomment %}

{% assign DEBUG = debug | default: request.params.debug == '1' %}
{% assign acceptanceId = request.params.acceptanceid | default: '' | strip %}

{% if acceptanceId == '' %}

  <div class="hit-alert hit-alert-warning" role="alert">
    Missing acceptance id.
  </div>

{% else %}

  {% fetchxml acc_q %}
  <fetch top="1" mapping="logical">
    <entity name="hit_offeringacceptance">

      <attribute name="hit_offeringacceptanceid" />
      <attribute name="hit_firstname" />
      <attribute name="hit_lastname" />
      <attribute name="hit_email" />
      <attribute name="hit_mobilephone" />
      <attribute name="hit_pricinglabel" />
      <attribute name="hit_baseamount" />
      <attribute name="hit_totalamounteffective" />
      <attribute name="hit_acceptancestatus" />
      <attribute name="hit_stripeclientsecret" />
      <attribute name="hit_stripepaymentintentid" />

      <filter>
        <condition
          attribute="hit_offeringacceptanceid"
          operator="eq"
          value="{{ acceptanceId | escape }}" />
      </filter>

      <link-entity
        name="hit_offering"
        from="hit_offeringid"
        to="hit_offering"
        alias="off">

        <attribute name="hit_offeringname" />

      </link-entity>

    </entity>
  </fetch>
  {% endfetchxml %}

  {% assign acc = acc_q.results.entities | first %}

  {% if acc == nil %}

    <div class="hit-alert hit-alert-warning" role="alert">
      Acceptance not found.
    </div>

  {% else %}

    {% assign offeringName = acc['off.hit_offeringname'] | default: 'Sponsorship' %}
    {% assign pricingLabel = acc.hit_pricinglabel | default: '' %}

    {% assign totalAmount = acc.hit_totalamounteffective | default: acc.hit_baseamount | default: 0 %}

    {% if totalAmount.value %}
      {% assign totalAmount = totalAmount.value %}
    {% endif %}

    <div class="hit-acceptance hit-acceptance--sponsorship"
         data-context="donation"
         data-acceptance-id="{{ acc.hit_offeringacceptanceid }}">

<div class="hit-acceptance__grid">

        <!-- =======================================================
             LEFT: DONATION SUMMARY
             ======================================================= -->

        <aside class="hit-acceptance__left">

          <div class="hit-card hit-sponsorship-summary">

            <div class="hit-sponsorship-summary__eyebrow">
              Sponsorship
            </div>

            <h1 class="hit-sponsorship-summary__title">
              {{ offeringName | escape }}
            </h1>

            {% if pricingLabel != blank %}
              <div class="hit-sponsorship-summary__option">
                {{ pricingLabel | escape }}
              </div>
            {% endif %}

            <div class="hit-sponsorship-summary__amount">
              ${{ totalAmount }}
            </div>

            <div class="hit-sponsorship-summary__description">
              Sponsorship gives you access to programs, benefits and opportunities
to support the disability sport and recreation community.
            </div>

            <ul class="hit-benefit-list">

              <li class="hit-benefit-list__item">
                <span class="hit-benefit-list__icon" aria-hidden="true">✓</span>
                <span>Sponsorship Benefits</span>
              </li>

              <li class="hit-benefit-list__item">
                <span class="hit-benefit-list__icon" aria-hidden="true">✓</span>
                <span>Secure online payment</span>
              </li>

              <li class="hit-benefit-list__item">
                <span class="hit-benefit-list__icon" aria-hidden="true">✓</span>
                <span>Your receipt will be sent by email</span>
              </li>

            </ul>

          </div>

        </aside>

        <!-- =======================================================
             RIGHT: CONTACT DETAILS
             ======================================================= -->

        <main class="hit-acceptance__right">

          <div class="hit-card hit-form-card">

            <h2 class="hit-heading">
              Tell us about yourself
            </h2>

            <p class="hit-subtitle">
              We’ll use these details to issue your receipt and keep you updated.
            </p>

            <div class="hit-status-pill" aria-label="Current step">
              <span class="hit-status-pill__indicator" aria-hidden="true"></span>
              <span>Enter your details to continue</span>
            </div>

            <input type="hidden"
                   id="acceptanceId"
                   value="{{ acc.hit_offeringacceptanceid }}">

            <!-- Error summary remains present in the DOM for accessibility -->

            <div id="errSummary"
                 class="hit-error-summary"
                 role="alert"
                 aria-atomic="true"
                 hidden>

              <h3 class="hit-error-summary__title">
                There’s a problem
              </h3>

              <ul id="errSummaryList"
                  class="hit-error-summary__list"></ul>

            </div>

            <form class="hit-form" novalidate>

              <!-- ORGANISATION TOGGLE -->

              <div class="hit-form-section">

                <div class="hit-checkbox">

                  <input type="checkbox"
                         id="orgToggle"
                         class="hit-checkbox__input"
                         aria-controls="orgSection"
                         aria-expanded="false">

                  <div class="hit-checkbox__content">

                    <label class="hit-checkbox__label" for="orgToggle">
                      I am acting on behalf of an organisation
                    </label>

                    <span class="hit-checkbox__help">
                      Select this option to include the organisation name and your role.
                    </span>

                  </div>

                </div>

              </div>

              <!-- ORGANISATION DETAILS -->

              <div id="orgSection"
                   class="hit-form-section hit-form-section--plain"
                   hidden>

                <div class="hit-field">

                  <label class="hit-label" for="organisation">
                    Organisation name
                    <span class="hit-required">*</span>
                  </label>

                  <input id="organisation"
                         class="hit-input"
                         type="text"
                         autocomplete="organization"
                         aria-describedby="organisationError">

                  <p class="hit-error-message"
                     id="organisationError"></p>

                </div>

                <div class="hit-field">

                  <label class="hit-label" for="role">
                    Your role
                    <span class="hit-required">*</span>
                  </label>

                  <input id="role"
                         class="hit-input"
                         type="text"
                         autocomplete="organization-title"
                         aria-describedby="roleError">

                  <p class="hit-error-message"
                     id="roleError"></p>

                </div>

              </div>

              <!-- CONTACT DETAILS -->

              <div class="hit-form-section hit-form-section--plain">

                <div class="hit-field-row">

                  <div class="hit-field">

                    <label class="hit-label" for="firstName">
                      First name
                      <span class="hit-required">*</span>
                    </label>

                    <input id="firstName"
                           class="hit-input"
                           type="text"
                           autocomplete="given-name"
                           value="{{ acc.hit_firstname | escape }}"
                           aria-describedby="firstNameError"
                           required>

                    <p class="hit-error-message"
                       id="firstNameError"></p>

                  </div>

                  <div class="hit-field">

                    <label class="hit-label" for="lastName">
                      Last name
                      <span class="hit-required">*</span>
                    </label>

                    <input id="lastName"
                           class="hit-input"
                           type="text"
                           autocomplete="family-name"
                           value="{{ acc.hit_lastname | escape }}"
                           aria-describedby="lastNameError"
                           required>

                    <p class="hit-error-message"
                       id="lastNameError"></p>

                  </div>

                </div>

                <div class="hit-field">

                  <label class="hit-label" for="email">
                    Email
                    <span class="hit-required">*</span>
                  </label>

                  <input id="email"
                         class="hit-input"
                         type="email"
                         autocomplete="email"
                         value="{{ acc.hit_email | escape }}"
                         aria-describedby="emailError"
                         required>

                  <p class="hit-error-message"
                     id="emailError"></p>

                </div>

                <div class="hit-field">

                  <label class="hit-label" for="mobile">
                    Mobile
                  </label>

                  <input id="mobile"
                         class="hit-input"
                         type="tel"
                         autocomplete="tel"
                         value="{{ acc.hit_mobilephone | escape }}"
                         aria-describedby="mobileHelp">

                  <p class="hit-help" id="mobileHelp">
                    Optional. Include a mobile number if you’d like SMS updates.
                  </p>

                </div>

              </div>

              <!-- CONTINUE -->

              {% if DEBUG %}

                <div class="hit-debug">

                  Status:
                  {{ acc.hit_acceptancestatus }}

                  <br><br>

                  Client Secret Exists:
                  {% if acc.hit_stripeclientsecret %}
                    YES
                  {% else %}
                    NO
                  {% endif %}

                  <br><br>

                  Payment Intent:
                  {{ acc.hit_stripepaymentintentid }}

                  <br><br>

                  Route Attempt:
                  {{ request.params.routeattempt }}

                </div>

              {% endif %}

              <div class="hit-form-actions">

                <button id="continueBtn"
                        type="button"
                        class="hit-button hit-button--primary">

                  <span class="hit-button__text">
                    Continue
                  </span>

                  <span class="hit-button__loading">
                    <span class="hit-spinner" aria-hidden="true"></span>
                    <span>Saving...</span>
                  </span>

                </button>

                <p class="hit-form-footnote">
                  Your details will be saved before continuing to secure payment.
                </p>

              </div>

            </form>

          </div>

        </main>

      </div>

    </div>

    <style>
      .hit-sponsorship-summary__description,
      .hit-sponsorship-summary__description > * {
        max-width: 100%;
        width: 100%;
        min-width: 0;
      }

      .hit-sponsorship-summary__description {
        overflow-wrap: anywhere;
        word-break: break-word;
      }

      .hit-sponsorship-summary__description ul,
      .hit-sponsorship-summary__description ol,
      .hit-sponsorship-summary__description p,
      .hit-sponsorship-summary__description img {
        max-width: 100%;
        width: 100%;
      }

      .hit-sponsorship-summary__description ul,
      .hit-sponsorship-summary__description ol {
        margin: 0.75rem 0 0;
        padding-left: 1.25rem;
        list-style-position: outside;
      }

      .hit-sponsorship-summary__description li {
        margin: 0 0 0.4rem;
        padding-left: 0.2rem;
        overflow-wrap: anywhere;
        word-break: break-word;
      }
    </style>

    <script>
      (function(){

        const root = document.querySelector(
          '.hit-acceptance--sponsorship[data-acceptance-id="{{ acc.hit_offeringacceptanceid }}"]'
        );

        if (!root) {
          console.error("Donation acceptance root element was not found.");
          return;
        }

        const orgToggle = root.querySelector("#orgToggle");
        const orgSection = root.querySelector("#orgSection");
        const continueButton = root.querySelector("#continueBtn");

        const errorSummary = root.querySelector("#errSummary");
        const errorSummaryList = root.querySelector("#errSummaryList");
        const pendingPaymentValidationUrl = "{{ settings['Flow/AcceptanceStatusValidation'] | default: '' }}";

        /*
         * The Offering Acceptance router selects the next section based on
         * the Acceptance Status.
         *
         * After this form PATCHes the acceptance, Power Automate updates the
         * status asynchronously to Pending Payment.
         *
         * The first router request can therefore occur before Pending Payment
         * has been set. If the router returns this donation-details section
         * again with waitforpayment=1, this script waits briefly and requests
         * the router again using a unique URL.
         *
         * When the status reaches Pending Payment, the router returns the
         * payment section. Because this script is not rendered in that section,
         * the retry process ends automatically.
         */

        const currentUrl = new URL(window.location.href);

        const waitingForPayment =
          currentUrl.searchParams.get("waitforpayment") === "1";

        const parsedRouteAttempt =
          parseInt(currentUrl.searchParams.get("routeattempt") || "0", 10);

        const currentRouteAttempt =
          Number.isFinite(parsedRouteAttempt)
            ? parsedRouteAttempt
            : 0;

        const maximumRouteAttempts = 20;
        const routeRetryDelayMilliseconds = 1250;

        function getElement(id){
          return root.querySelector("#" + id);
        }

        function getValue(id){
          const element = getElement(id);

          if (!element) {
            return "";
          }

          return String(element.value || "").trim();
        }

        function setErrorText(errorId, message){
          const errorElement = getElement(errorId);

          if (!errorElement) {
            return;
          }

          errorElement.textContent = message || "";
          errorElement.style.display = message ? "block" : "none";
        }

        function setInvalid(inputId, errorId, message){
          const input = getElement(inputId);

          if (input) {
            input.setAttribute(
              "aria-invalid",
              message ? "true" : "false"
            );
          }

          setErrorText(errorId, message);
        }

        function clearErrorSummary(){
          if (errorSummaryList) {
            errorSummaryList.innerHTML = "";
          }

          if (errorSummary) {
            errorSummary.hidden = true;
            errorSummary.removeAttribute("tabindex");
          }
        }

        function addErrorSummaryItem(message){
          if (!errorSummaryList) {
            return;
          }

          const item = document.createElement("li");
          item.textContent = message;
          errorSummaryList.appendChild(item);
        }

        function showErrorSummary(){
          if (!errorSummary) {
            return;
          }

          errorSummary.hidden = false;
          errorSummary.setAttribute("tabindex", "-1");
          errorSummary.focus();
        }

        function isValidEmail(value){
          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
        }

        function setOrganisationExpanded(expanded){
          if (!orgToggle || !orgSection) {
            return;
          }

          orgToggle.setAttribute(
            "aria-expanded",
            expanded ? "true" : "false"
          );

          orgSection.hidden = !expanded;

          if (!expanded) {
            setInvalid(
              "organisation",
              "organisationError",
              ""
            );

            setInvalid(
              "role",
              "roleError",
              ""
            );
          }
        }

        function setLoading(isLoading, loadingMessage){
          if (!continueButton) {
            return;
          }

          const buttonText =
            continueButton.querySelector(".hit-button__text");

          const buttonLoading =
            continueButton.querySelector(".hit-button__loading");

          const loadingText =
            buttonLoading
              ? buttonLoading.querySelector("span:last-child")
              : null;

          continueButton.disabled = isLoading;
          continueButton.classList.toggle("is-loading", isLoading);

          if (buttonText) {
            buttonText.style.display =
              isLoading ? "none" : "inline";
          }

          if (buttonLoading) {
            buttonLoading.style.display =
              isLoading ? "inline-flex" : "none";
          }

          if (loadingText && loadingMessage) {
            loadingText.textContent = loadingMessage;
          }
        }

        function disableFormWhileRouting(){
          root.querySelectorAll(
            "input, select, textarea, button"
          ).forEach(function(element){
            element.disabled = true;
          });
        }

        function buildRouterUrl(attempt){
          const targetUrl = new URL(
            window.location.pathname,
            window.location.origin
          );

          targetUrl.searchParams.set(
            "page",
            "offering-acceptance"
          );

          targetUrl.searchParams.set(
            "acceptanceid",
            "{{ acc.hit_offeringacceptanceid }}"
          );

          targetUrl.searchParams.set(
            "waitforpayment",
            "1"
          );

          targetUrl.searchParams.set(
            "routeattempt",
            String(attempt)
          );

          /*
           * Ensure that every request has a unique URL so the browser performs
           * a new navigation rather than treating it as the current location.
           */
          targetUrl.searchParams.set(
            "_ts",
            String(Date.now())
          );

          return targetUrl.toString();
        }

        function redirectToRouter(){
          setLoading(
            true,
            "Preparing payment..."
          );

          disableFormWhileRouting();

          window.location.replace(
            buildRouterUrl(0)
          );
        }

        function stopRouterRetry(){
          const cleanUrl = new URL(window.location.href);

          cleanUrl.searchParams.delete("waitforpayment");
          cleanUrl.searchParams.delete("routeattempt");
          cleanUrl.searchParams.delete("_ts");

          window.history.replaceState(
            {},
            document.title,
            cleanUrl.toString()
          );

          root.querySelectorAll(
            "input, select, textarea, button"
          ).forEach(function(element){
            element.disabled = false;
          });

          if (orgSection && !orgToggle.checked) {
            orgSection.hidden = true;
          }

          setLoading(false);

          clearErrorSummary();

          addErrorSummaryItem(
            "Your details were saved, but the payment page is taking longer than expected to become available. Please refresh the page to continue."
          );

          showErrorSummary();
        }

        function retryRouter(){
          if (currentRouteAttempt >= maximumRouteAttempts) {
            stopRouterRetry();
            return;
          }

          setLoading(
            true,
            "Preparing payment..."
          );

          disableFormWhileRouting();

          window.setTimeout(function(){
            window.location.replace(
              buildRouterUrl(currentRouteAttempt + 1)
            );
          }, routeRetryDelayMilliseconds);
        }

        /*
         * If this section has been returned by the router while waiting for
         * Pending Payment, do not submit the form again. Request the router
         * again after a short delay.
         */
        if (waitingForPayment) {
          retryRouter();
          return;
        }

        if (orgToggle && orgSection) {
          setOrganisationExpanded(orgToggle.checked);

          orgToggle.addEventListener(
            "change",
            function(){
              setOrganisationExpanded(
                orgToggle.checked
              );
            }
          );
        }

        async function getCsrfToken(){
          const response = await fetch(
            "/_layout/tokenhtml",
            {
              method: "GET",
              credentials: "same-origin",
              cache: "no-store"
            }
          );

          if (!response.ok) {
            throw new Error(
              "Unable to retrieve request token."
            );
          }

          const tokenHtml = await response.text();

          const tokenDocument =
            new DOMParser().parseFromString(
              tokenHtml,
              "text/html"
            );

          const tokenInput =
            tokenDocument.querySelector(
              "input[name='__RequestVerificationToken']"
            );

          if (!tokenInput || !tokenInput.value) {
            throw new Error(
              "Request token was not found."
            );
          }

          return tokenInput.value;
        }

        function validate(){
          clearErrorSummary();

          setInvalid(
            "firstName",
            "firstNameError",
            ""
          );

          setInvalid(
            "lastName",
            "lastNameError",
            ""
          );

          setInvalid(
            "email",
            "emailError",
            ""
          );

          setInvalid(
            "organisation",
            "organisationError",
            ""
          );

          setInvalid(
            "role",
            "roleError",
            ""
          );

          const firstName = getValue("firstName");
          const lastName = getValue("lastName");
          const email = getValue("email");

          let isValid = true;
          let firstInvalidField = null;

          function registerError(
            inputId,
            errorId,
            fieldMessage,
            summaryMessage
          ){
            isValid = false;

            setInvalid(
              inputId,
              errorId,
              fieldMessage
            );

            addErrorSummaryItem(
              summaryMessage
            );

            if (!firstInvalidField) {
              firstInvalidField =
                getElement(inputId);
            }
          }

          if (!firstName) {
            registerError(
              "firstName",
              "firstNameError",
              "Please enter your first name.",
              "First name is required."
            );
          }

          if (!lastName) {
            registerError(
              "lastName",
              "lastNameError",
              "Please enter your last name.",
              "Last name is required."
            );
          }

          if (!email) {
            registerError(
              "email",
              "emailError",
              "Please enter your email address.",
              "Email is required."
            );
          } else if (!isValidEmail(email)) {
            registerError(
              "email",
              "emailError",
              "Please enter a valid email address.",
              "Email must be a valid email address."
            );
          }

          if (orgToggle && orgToggle.checked) {
            const organisation =
              getValue("organisation");

            const role =
              getValue("role");

            if (!organisation) {
              registerError(
                "organisation",
                "organisationError",
                "Please enter the organisation name.",
                "Organisation name is required when acting on behalf of an organisation."
              );
            }

            if (!role) {
              registerError(
                "role",
                "roleError",
                "Please enter your role.",
                "Your role is required when acting on behalf of an organisation."
              );
            }
          }

          if (!isValid) {
            showErrorSummary();

            if (firstInvalidField) {
              window.setTimeout(
                function(){
                  firstInvalidField.focus();
                },
                0
              );
            }
          }

          return isValid;
        }

        async function triggerPendingPaymentValidation(id){
          if (!pendingPaymentValidationUrl) {
            return null;
          }

          const response = await fetch(pendingPaymentValidationUrl, {
            method: "POST",
            credentials: "same-origin",
            cache: "no-store",
            headers: {
              "Accept": "application/json",
              "Content-Type": "application/json",
              "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
              "Pragma": "no-cache",
              "Expires": "0"
            },
            body: JSON.stringify({
              acceptanceId: id
            })
          });

          if (!response.ok) {
            throw new Error("Pending payment validation flow failed.");
          }

          try {
            return await response.json();
          } catch (_ignore) {
            return null;
          }
        }

        async function updateAcceptance(){
          const id = getValue("acceptanceId");

          if (!id) {
            throw new Error(
              "Acceptance identifier is missing."
            );
          }

          const payload = {
            hit_firstname:
              getValue("firstName"),

            hit_lastname:
              getValue("lastName"),

            hit_email:
              getValue("email"),

            hit_mobilephone:
              getValue("mobile"),

            hit_totalamounteffective:
              {{ totalAmount | json }},

            hit_baseamount:
              {{ totalAmount | json }},

            hit_organisationinput:
              orgToggle && orgToggle.checked
                ? getValue("organisation")
                : null,

            hit_contactroleinput:
              orgToggle && orgToggle.checked
                ? getValue("role")
                : null
          };

          const token =
            await getCsrfToken();

          const response = await fetch(
            "/_api/hit_offeringacceptances(" +
              id +
            ")",
            {
              method: "PATCH",
              credentials: "same-origin",
              cache: "no-store",
              headers: {
                "Content-Type": "application/json",
                "Accept": "application/json",
                "OData-MaxVersion": "4.0",
                "OData-Version": "4.0",
                "__RequestVerificationToken": token,
                "If-Match": "*"
              },
              body: JSON.stringify(payload)
            }
          );

          if (!response.ok) {
            const errorText =
              await response.text();

            console.error(
              "Offering Acceptance update failed:",
              response.status,
              errorText
            );

            throw new Error(
              "Acceptance update failed."
            );
          }

          try {
            await triggerPendingPaymentValidation(id);
          } catch (flowError) {
            console.warn("Pending payment validation flow call failed after PATCH. Continuing router retry flow.", flowError);
          }

          return id;
        }

        async function handleContinue(){
          if (!continueButton) {
            return;
          }

          if (
            continueButton.classList.contains(
              "is-loading"
            )
          ) {
            return;
          }

          if (!validate()) {
            return;
          }

          setLoading(
            true,
            "Saving..."
          );

          try {
            await updateAcceptance();

            /*
             * The PATCH is complete, but the orchestration flow may still be
             * changing the status to Pending Payment. Navigate through the
             * acceptance router and allow the retry mode above to wait for
             * the payment section.
             */
            redirectToRouter();

          } catch (error) {
            console.error(error);

            clearErrorSummary();

            addErrorSummaryItem(
              "Your details could not be saved. Please try again."
            );

            showErrorSummary();

            setLoading(false);
          }
        }

        if (continueButton) {
          continueButton.addEventListener(
            "click",
            handleContinue
          );
        }

      })();
    </script>

  {% endif %}

{% endif %}
"
}
